import unittest
from pathlib import Path

from dna_sequence_analyzer.dna_nucleotide import DNANucleotide
from dna_sequence_analyzer.dna_reader import read_DNA
from dna_sequence_analyzer.dna_sequence import DNASequence


class TestReadDNA(unittest.TestCase):
    def test_invalid_file_path_raises_exception(self):
        with self.assertRaises(FileNotFoundError):
            read_DNA(Path("this_path_doesnt_exist"))

    def test_parses_fasta_file_correctly(self):
        sequences = read_DNA(Path("data/nuccore_bacterial_genome_71c6a768.fasta"))
        self.assertEqual(len(sequences), 1)
        sample_dna: str = ""
        self.assertEqual(
            sequences[0],
            DNASequence([DNANucleotide[n] for n in sample_dna]),
        )
